const {chromium}=require('playwright-core');
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const {pathToFileURL}=require('node:url');
const root=__dirname,out=path.join(root,'evidence-meeting-20261105');fs.mkdirSync(out,{recursive:true});
(async()=>{const browser=await chromium.launch({headless:true,executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe'});const page=await browser.newPage({viewport:{width:1480,height:1140}});const errors=[],results=[];page.on('pageerror',e=>errors.push(e.message));await page.goto(pathToFileURL(path.join(root,'Steam接入Demo.html')).href);const api=(n,a)=>page.evaluate(([n,a])=>window.demo[n](a),[n,a]),get=()=>api('getState'),click=a=>page.locator('#screen [data-action="'+a+'"]:not([inert] *)').first().click();
const test=async(name,run)=>{try{await api('reset');await api('setOrientation','portrait');await run();results.push({name,status:'passed'});console.log('PASS',name)}catch(e){results.push({name,status:'failed',message:e.message});console.error('FAIL',name,e.message)}};
const prepared=async()=>{for(let i=0;i<8;i++){if(['steam','login'].includes((await get()).page))return;await api('advance')}throw Error('prepare timeout')};
const shot=async(name,fixture,orientation='portrait')=>{await api('setOrientation',orientation);await api('loadFixture',fixture);await api('setReviewOpen',false);await page.locator('#viewLabel').click();await page.locator('#screen').screenshot({path:path.join(out,name+'.png')})};
await test('首次只确认协议，未勾不可继续，阅读不自动同意',async()=>{await click('enter-steam');assert.equal((await get()).page,'mode');assert.equal(await page.locator('#consent').isChecked(),false);assert.equal(await page.locator('[data-action="confirm-mode"]').isDisabled(),true);assert.equal(await page.locator('#remember,[data-action="select-mode"]').count(),0);assert.equal(await page.locator('#consentTitle').innerText(),'进入 Steam');await click('read-agreement');assert.equal((await get()).page,'legal');await click('legal-close');assert.equal(await page.locator('#consent').isChecked(),false);await click('library');assert.equal((await get()).pref.accepted,0);await click('enter-steam');await page.locator('#consent').check();await click('confirm-mode');assert.equal((await get()).currentMode,'gamepad');await prepared();assert.equal((await get()).page,'login')});
await test('旧版已登录首次仍需协议，保留登录后进入大屏',async()=>{await api('loadFixture','legacy-mode');assert.equal((await get()).page,'mode');assert.equal((await get()).loggedIn,true);await page.locator('#consent').check();await click('confirm-mode');await prepared();assert.equal((await get()).page,'steam');assert.equal((await get()).currentMode,'gamepad')});
await test('已同意直入；旧窗口偏好被忽略，新会话固定大屏',async()=>{await api('loadFixture','steam-library');await page.evaluate(()=>{const key='gamehub-steam-demo-v1',p=JSON.parse(localStorage.getItem(key));p.preference='window';localStorage.setItem(key,JSON.stringify(p))});await api('coldStart');await click('library');await click('enter-steam');assert.notEqual((await get()).page,'mode');await prepared();assert.equal((await get()).currentMode,'gamepad');assert.equal(await page.locator('[data-action="mode-settings"],[data-action="setting-select"]').count(),0)});
await test('模式仅在悬浮窗右上设置内，切换保留目标及输入',async()=>{for(const fixture of ['game-waiting','login-failed','qr-scanned']){await api('loadFixture',fixture);await click('bubble');assert.equal(await page.locator('[data-action="session-mode"]').count(),0);assert.equal(await page.locator('.bubble-menu-head [data-action="bubble-settings"]').count(),1);const before=await get();await click('bubble-settings');await page.locator('[data-action="session-mode"][data-mode="window"]').click();const after=await get();assert.equal(after.currentMode,'window');for(const k of ['page','steamPage','game','gameStatus','pendingGame','pendingTarget','loginUser','loginPassword','loginPending','qrStatus'])assert.deepEqual(after[k],before[k],k);await click('bubble-main');assert.equal(await page.locator('[data-action="session-mode"]').count(),0)}});
await test('模式切换仅本会话，返回恢复；结束后新启动大屏',async()=>{await api('loadFixture','bubble-settings');assert.equal((await get()).currentMode,'window');await click('bubble-main');await click('library');await click('enter-steam');assert.equal((await get()).currentMode,'window');await api('newSession');await click('enter-steam');await prepared();assert.equal((await get()).currentMode,'gamepad')});
await test('两方向最小化与100至150缩放无回归',async()=>{for(const orientation of ['portrait','landscape']){await api('loadFixture','bubble-open');await api('setOrientation',orientation);await page.locator('#sessionScale').evaluate(e=>{e.value='150';e.dispatchEvent(new Event('input',{bubbles:true}))});assert.equal((await get()).scale,150);assert.equal(await page.locator('.steam').evaluate(e=>getComputedStyle(e).zoom),'1.5');assert.equal(await page.locator('[data-action="minimize-bubble"]').count(),1);await click('minimize-bubble');assert.equal((await get()).bubbleMinimized,true);assert.equal((await get()).session,true);await click('bubble');await click('bubble-settings');const box=await page.locator('.bubble-menu').boundingBox(),screen=await page.locator('#screen').boundingBox();assert(box.y>=screen.y&&box.y+box.height<=screen.y+screen.height);await click('minimize-bubble');assert.equal((await get()).currentMode,'gamepad')}});
await test('启动落地页四选项及横竖屏默认不变',async()=>{await api('loadFixture','landing-settings');assert.deepEqual(await page.locator('[data-action="landing-select"] strong').allTextContents(),['主页','社区','游戏库','Steam']);await api('reset');await api('coldStart');assert.equal((await get()).page,'home');await api('setOrientation','landscape');await api('coldStart');assert.equal((await get()).page,'library')});
await test('全部演示状态可切换',async()=>{for(const fixture of await api('getFixtures')){await api('loadFixture',fixture.key);assert(await page.locator('#screen').innerText(),fixture.key)}assert(!errors.length,errors.join('\n'))});
for(const [name,fixture,orientation] of [['01-library','library'],['02-consent','first-mode'],['03-prepare','downloading'],['04-steam','steam-library'],['05-bubble','bubble-open'],['05-bubble-settings','bubble-settings'],['09-login','qr-ready'],['13-consent-landscape','first-mode','landscape'],['14-bubble-minimized','bubble-mini'],['31-landing-guide','landing-guide'],['36-bubble-landscape','bubble-open','landscape'],['36-bubble-settings-landscape','bubble-settings','landscape'],['37-bubble-scale150','bubble-scale150']])await shot(name,fixture,orientation);
await browser.close();fs.writeFileSync(path.join(out,'verification.json'),JSON.stringify({results,errors},null,2));if(results.some(x=>x.status!=='passed')||errors.length)process.exitCode=1;
})();
